// Robust flattener + dedupe + top-25 for Yahoo screener outputs (and mixed rows)

// ---- config
const LIMIT = 5;

// ---- helpers
function normNum(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (v == null) return 0;
  const n = parseFloat(String(v).replace('%','').trim());
  return isFinite(n) ? n : 0;
}

function cleanSymbol(s) {
  return (s || '').toString().trim().toUpperCase();
}

function isLikelyEquity(sym, quoteType) {
  if (!sym) return false;
  if (sym.startsWith('^')) return false;          // indexes (^GSPC)
  if (sym.includes('=')) return false;            // FX pairs, etc.
  if (quoteType && quoteType !== 'EQUITY') return false;
  return true;
}

// Extract array of quote-like rows from any incoming item
function extractRowsFromItem(it) {
  const row = it?.json ?? it ?? {};
  // Yahoo predefined screener shape:
  // { finance: { result: [ { quotes: [...] } ] } }
  const quotes = row.finance?.result?.[0]?.quotes;
  if (Array.isArray(quotes) && quotes.length) {
    return quotes.map(q => ({
      symbol: q.symbol,
      changePct: normNum(q.regularMarketChangePercent),
      quoteType: q.quoteType
    }));
  }
  // Already a flat row
  return [{
    symbol: row.symbol || row.ticker,
    changePct: normNum(
      row.changePct ??
      row.regularMarketChangePercent ??
      row.changesPercentage ??
      row.percentchange
    ),
    quoteType: row.quoteType
  }];
}

// ---- main
const bucket = [];
for (const it of items) {
  const rows = extractRowsFromItem(it);
  for (const r of rows) bucket.push(r);
}

// Deduplicate & filter
const seen = new Set();
const flat = [];
for (const r of bucket) {
  const sym = cleanSymbol(r.symbol);
  if (!isLikelyEquity(sym, r.quoteType)) continue;
  if (seen.has(sym)) continue;
  seen.add(sym);
  flat.push({ symbol: sym, changePct: normNum(r.changePct) });
}

// Sort by absolute % move desc and take top N
flat.sort((a, b) => Math.abs(b.changePct) - Math.abs(a.changePct));
const top = flat.slice(0, LIMIT);

// Output as one item per ticker
return top.map(x => ({ json: { symbol: x.symbol, changePct: x.changePct } }));

// Function Item node — returns ONE plain object

function round(x, d = 2) { return Number((x ?? 0).toFixed(d)); }

function computeSeriesMetricsEnhanced(series) {
  const cfg = { window: 50, H: 6, z1Thresh: 1.5, zHThresh: 1.8, pctThresh: 0.75, atrPeriod: 14, atrMult: 1.0, volSpikeMult: 1.8 };

  const ts = Array.isArray(series.timestamp) ? series.timestamp.filter(Number.isFinite) : [];
  const close = (Array.isArray(series.close) ? series.close : []).filter(Number.isFinite);
  const high  = (Array.isArray(series.high)  ? series.high  : []).filter(Number.isFinite);
  const low   = (Array.isArray(series.low)   ? series.low   : []).filter(Number.isFinite);
  const vol   = (Array.isArray(series.volume)? series.volume: []).filter(x => Number.isFinite(x) && x >= 0);

  const n = close.length;
  const latestTs = ts.length ? new Date(ts[ts.length - 1] * 1000).toISOString() : new Date().toISOString();

  if (n < 3) {
    return { symbol: series.symbol ?? null, note: "insufficient_bars", volatilityFlag: false, timestamp: latestTs };
  }

  const last = close[n - 1], prev = close[n - 2];
  const change = last - prev;
  const changePct = prev ? (change / prev) * 100 : 0;

  // 1-bar log-return z-score
  const rets = [];
  for (let i = 1; i < n; i++) if (close[i-1] > 0 && close[i] > 0) rets.push(Math.log(close[i] / close[i-1]));
  const W = Math.min(cfg.window, rets.length);
  const R1 = rets.slice(-W);
  const mean1 = R1.reduce((a, b) => a + b, 0) / (R1.length || 1);
  const std1  = Math.sqrt(R1.reduce((a, b) => a + (b - mean1) ** 2, 0) / Math.max(R1.length - 1, 1)) || 1e-9;
  const z1 = (rets[rets.length - 1] - mean1) / std1;

  // H-bar z-score (drift)
  let zH = 0;
  if (n > cfg.H) {
    const retH = Math.log(close[n - 1] / close[n - 1 - cfg.H]);
    const RH = [];
    for (let i = cfg.H; i < n; i++) if (close[i-cfg.H] > 0 && close[i] > 0) RH.push(Math.log(close[i] / close[i-cfg.H]));
    const WH = Math.min(cfg.window, RH.length);
    const RHw = RH.slice(-WH);
    const meanH = RHw.reduce((a,b)=>a+b,0) / (RHw.length || 1);
    const stdH  = Math.sqrt(RHw.reduce((a,b)=>a+(b-meanH)**2,0) / Math.max(RHw.length-1,1)) || 1e-9;
    zH = (retH - meanH) / stdH;
  }

  // ATR-based move (if highs/lows available)
  let moveVsATR = 0;
  if (high.length === n && low.length === n) {
    const tr = [];
    for (let i = 1; i < n; i++) {
      const hl = high[i] - low[i];
      const hc = Math.abs(high[i] - close[i - 1]);
      const lc = Math.abs(low[i] - close[i - 1]);
      tr.push(Math.max(hl, hc, lc));
    }
    const atr = tr.slice(-cfg.atrPeriod).reduce((a,b)=>a+b,0) / Math.max(cfg.atrPeriod, 1);
    moveVsATR = atr ? Math.abs(change) / atr : 0;
  }

  // Volume spike (if volume)
  let volSpike = false;
  if (vol.length === n && n > 21) {
    const avgVol = vol.slice(-21, -1).reduce((a,b)=>a+b,0) / 20;
    volSpike = avgVol ? (vol[n - 1] > cfg.volSpikeMult * avgVol) : false;
  }

  const flag = Math.abs(z1) >= cfg.z1Thresh ||
               Math.abs(zH) >= cfg.zHThresh ||
               Math.abs(changePct) >= cfg.pctThresh ||
               moveVsATR >= cfg.atrMult ||
               volSpike;

  return {
    symbol: series.symbol ?? null,
    price: round(last),
    change: round(change),
    changePercent: round(changePct),
    z1: round(z1, 2),
    zH: round(zH, 2),
    moveVsATR: round(moveVsATR, 2),
    volSpike,
    volatilityFlag: !!flag,
    timestamp: latestTs
  };
}

// ---- detect current item shape and ALWAYS return ONE object ----
const j = $json;

try {
  // A) /v8/finance/chart  (single symbol)
  if (j?.chart?.result?.[0]) {
    const r0 = j.chart.result[0];
    const q  = r0.indicators?.quote?.[0] || {};
    const series = {
      symbol: r0.meta?.symbol ?? null,
      timestamp: r0.timestamp || [],
      close: q.close || [],
      high: q.high || [],
      low: q.low || [],
      volume: q.volume || []
    };
    return computeSeriesMetricsEnhanced(series);
  }

  // B) spark single series: { symbol, timestamp[], close[] }
  if (j?.symbol && Array.isArray(j?.close)) {
    const series = { symbol: j.symbol, timestamp: j.timestamp || [], close: j.close || [], high: [], low: [], volume: [] };
    return computeSeriesMetricsEnhanced(series);
  }

  // C) quote snapshot (first element only if multiple)
  if (Array.isArray(j?.quoteResponse?.result) && j.quoteResponse.result.length) {
    const r = j.quoteResponse.result[0];
    const cp = r.regularMarketChangePercent ?? null;
    return {
      symbol: r.symbol ?? null,
      price: r.regularMarketPrice ?? null,
      changePercent: cp,
      z1: null, zH: null, moveVsATR: null, volSpike: null,
      volatilityFlag: Math.abs(cp ?? 0) >= 2.0,
      timestamp: new Date().toISOString()
    };
  }

  // D) fallback — unknown shape, but still return an object
  return { symbol: j.symbol ?? null, note: "unrecognized_shape", volatilityFlag: false, timestamp: new Date().toISOString(), keys: Object.keys(j || {}) };

} catch (e) {
  // Never throw: always return an object
  return { error: "parse_failed", message: e.message, volatilityFlag: false, timestamp: new Date().toISOString() };
}

/**
 * Align current items (with {data}) to symbols emitted by another node
 * named EXACTLY: Code - Dedupe and Sorting
 *
 * INPUT (this node):  [{json:{data:"..."}} , ...]
 * UPSTREAM node:      [{json:{symbol:"ABCD"}}, ...]
 * OUTPUT:             [{json:{symbol:"ABCD", data:"..."}} , ...]
 */

const SYMBOLS_NODE = 'Code - Dedupe and Sorting';  // <-- must match the node's label exactly
const CYCLE_IF_SHORT = false; // set true if you want to wrap symbols when data items > symbols

// Grab ALL items from the symbols node (runIndex 0)
const symItems = $items(SYMBOLS_NODE, 0) || [];
const nSym = symItems.length;

if (!nSym) {
  throw new Error(`No items from node "${SYMBOLS_NODE}". 
- Check the node name (must match exactly, including spaces and case).
- Ensure this node is executed BEFORE the current one (connect the flow).
- Open Executions → select "${SYMBOLS_NODE}" → confirm it produced items.`);
}

const out = [];
for (let i = 0; i < items.length; i++) {
  // Choose which symbol item to use
  let idx = i;
  if (idx >= nSym) {
    if (!CYCLE_IF_SHORT) break;            // stop if we don't want to cycle
    idx = i % nSym;                         // or cycle
  }
  const sym = symItems[idx]?.json?.symbol ?? null;

  // Accept either {data: "..."} or any json payload
  const dataPayload = (items[i].json && 'data' in items[i].json)
    ? items[i].json.data
    : items[i].json;

  out.push({
    json: {
      symbol: sym,
      data: dataPayload
    }
  });
}

return out;

/**
 * n8n Code (Function) node
 * INPUT items:  [{ json: { symbol: "NVDA", data: "<rss>...</rss>" } }, ...]
 * OUTPUT items: [{ json: { symbol: "NVDA", news: ["title — snippet", ...] } }, ...]
 */

const TOP_N = 5;        // max headlines per symbol
const SNIP = 240;       // snippet length
const REQUIRED_MATCH = false; // if true: keep only items that mention the ticker

function stripHtml(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[(.*?)\]\]>/gs, '$1')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tickerRegex(sym) {
  const esc = String(sym || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`(^|[^A-Za-z0-9])(?:\\$|NASDAQ:|NYSE:|AMEX:)?\\s*${esc}(?=$|[^A-Za-z0-9])`, 'i');
}

function getXmlFromJson(j) {
  if (typeof j === 'string') return j;
  if (typeof j?.data === 'string') return j.data;
  if (typeof j?.body === 'string') return j.body;
  // try any first string field as last resort
  for (const k of Object.keys(j || {})) {
    if (typeof j[k] === 'string') return j[k];
  }
  return '';
}

function parseRss(xml, symbol) {
  const reItem = /<item\b[\s\S]*?<\/item>/gi;
  const blocks = Array.from(xml.matchAll(reItem)).map(m => m[0]);
  if (!blocks.length) return [];

  const reTitle = /<title>([\s\S]*?)<\/title>/i;
  const reDesc  = /<description>([\s\S]*?)<\/description>/i;
  const reTick  = tickerRegex(symbol);

  const seen = new Set();
  const out = [];

  for (const block of blocks) {
    const t = stripHtml((block.match(reTitle)?.[1]) || '');
    const d = stripHtml((block.match(reDesc)?.[1]) || '');
    if (!t) continue;

    if (REQUIRED_MATCH && symbol && !reTick.test(`${t} ${d}`)) continue;

    const key = t.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    out.push(d ? `${t} — ${d.slice(0, SNIP)}` : t);
    if (out.length >= TOP_N) break;
  }
  return out;
}

// ---- process all incoming items
const out = [];
for (let i = 0; i < items.length; i++) {
  const input = items[i].json || {};
  const symbol = String(input.symbol || '').trim();
  const xml = getXmlFromJson(input);
  const news = xml ? parseRss(xml, symbol) : [];
  out.push({ json: { symbol, news } });
}

return out;

// Build Mistral chat bodies: one output item per input ticker,
// asking for a Telegram-ready MarkdownV2 message (no JSON).

const MAX_NEWS = 5;        // cap headlines
const MAX_LINE = 300;      // trim long lines

function fmt(n, d = 2) {
  if (n === null || n === undefined) return "n/a";
  const v = Number(n);
  return Number.isFinite(v) ? v.toFixed(d) : "n/a";
}

const out = [];

for (const itWrap of items) {
  const it = itWrap.json || {};

  // news lines
  const newsLines = Array.isArray(it.news) ? it.news : [];
  const newsBlock = newsLines
    .filter(Boolean)
    .slice(0, MAX_NEWS)
    .map(s => String(s).slice(0, MAX_LINE))
    .map(s => `- ${s}`)
    .join('\n') || '— no notable news —';

  // prompt: TASK first, then details, news last; use """ multiline
  const userContent = `"""
Task:
Provide a concise stock recommendation for Telegram.
Output must be a single MarkdownV2 message, no JSON, no code blocks.

Format:
*${it.symbol || 'SYM'}*
Score: *X/10*
Recommendation: *BUY/SELL/HOLD*
Projection (1w): *N.NN%*
Rationale: <one sentence>
Uncertainty: <one sentence>

Details:
Symbol: ${it.symbol || 'n/a'}
Timestamp: ${it.timestamp || 'n/a'}
Last price: ${fmt(it.price)}
Day change: ${fmt(it.change)} (${fmt(it.changePercent)}%)
Risk: z1=${fmt(it.z1)}, zH=${fmt(it.zH)}, moveVsATR=${fmt(it.moveVsATR)}, volSpike=${Boolean(it.volSpike)}, volatilityFlag=${Boolean(it.volatilityFlag)}

News (last 2 days):
${newsBlock}
"""`;

  out.push({
    json: {
      model: "mistral-small-latest",
      temperature: 0.3,
      // IMPORTANT: no response_format here; we want plain text MarkdownV2
      messages: [
        {
          role: "system",
          content:
            "You are a financial analytics assistant. Return one concise Telegram-ready MarkdownV2 message only. Do not return JSON. Do not use code blocks. Properly escape MarkdownV2 special characters."
        },
        { role: "user", content: userContent }
      ]
    }
  });
}

return out;
